Definition CSTd (txt : list Z) (srb : list (Z * Z)) (F : Z) (bv : nat -> Z) (M1 : mem) (ps : PML.pstate) (ch : Z) (bof dn : bool) (rep : PML.srep) (gp rdst : Z) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 12 (HarnessBsCB_blobs1.kr_b_005 ())).

