Lemma CSTd_ag : forall txt srb F bv (M1 M2 : mem) (SS : Z -> Prop) ps ch bof dn rep gp rdst,
  (forall a, SS a -> M2 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
  PTA.out SS (F + 464) 656 -> PTA.out SS (F + 96) 272 -> RDKC.text_out SS (F + 96) rep ->
  (match rep with PML.SShort _ => True | PML.SLong cap p _ => 0 <= cap /\ p mod 8 = 0 /\ forall a, in_shadow_of p cap a -> SS a end) ->
  blk_in_set SS (PML.ps_bptr ps) (PML.ps_bcap ps) -> blk_in_set SS (PML.ps_sb ps) (PML.ps_scap ps) -> blk_in_set SS ch 16384 -> Z.of_nat (length txt) < 2 ^ 26 ->
  CSTd txt srb F bv M1 ps ch bof dn rep gp rdst -> CSTd txt srb F bv M2 ps ch bof dn rep gp rdst.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 (HarnessBsCB_blobs1.kr_b_007 ())).
Qed.

